func BenchmarkWalkXFF(b *testing.B) {
	for _, n := range []int{1, 10, 100, 1000, 10000} {
		entries := make([]string, n)
		for i := range entries {
			entries[i] = "1.2.3.4"
		}
		headers := []string{strings.Join(entries, ", ")}

